const { makeOptions } = require('./options.cjs');
const args = process.argv.slice(2);
let limit;
if (args.length) {
  if (args.length !== 2 || args[0] !== '--limit' || !/^\d+$/.test(args[1])) {
    console.error('Usage: node cli.cjs [--limit NONNEGATIVE_INTEGER]');
    process.exit(2);
  }
  limit = Number(args[1]);
  if (!Number.isSafeInteger(limit)) { console.error('Limit out of range'); process.exit(2); }
}
console.log(JSON.stringify(makeOptions({ limit })));

