const test = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const path = require('node:path');
function run(args) {
  return spawnSync(process.execPath, [path.join(__dirname, '..', 'cli.cjs'), ...args], { encoding: 'utf8' });
}
test('default export limit', () => {
  const r = run([]);
  assert.equal(r.status, 0);
  assert.deepEqual(JSON.parse(r.stdout), { limit: 20, format: 'json' });
});
test('positive export limit', () => {
  const r = run(['--limit', '7']);
  assert.equal(r.status, 0);
  assert.deepEqual(JSON.parse(r.stdout), { limit: 7, format: 'json' });
});
test('invalid export limit', () => {
  const r = run(['--limit', '-1']);
  assert.equal(r.status, 2);
  assert.equal(r.stdout, '');
});

